// Normalise the Telegram update into one shape for the rest of the workflow
const msg = $('Telegram Trigger').first().json.message || {};
let input_type = 'text';
let file_id = null;
if (msg.voice) { input_type = 'voice'; file_id = msg.voice.file_id; }
else if (msg.audio) { input_type = 'voice'; file_id = msg.audio.file_id; }
else if (msg.photo && msg.photo.length) {
  input_type = 'photo';
  file_id = msg.photo[msg.photo.length - 1].file_id; // largest resolution
}
return [{ json: {
  chat_id: msg.chat ? String(msg.chat.id) : null,
  input_type,
  file_id,
  text: msg.text || '',
  caption: msg.caption || '',
} }];

// Build a Gemini request with the downloaded file inlined as base64
const bin = $input.first().binary.data;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let mime = bin.mimeType || '';
if (!mime || mime === 'application/octet-stream') mime = "audio/ogg";
const instruction = "Transcribe this voice message exactly as spoken. It is probably a question about a Tunisian administrative procedure, in Tunisian Darija, French, Modern Standard Arabic or English, often mixed in the same sentence.\nWrite Arabic and Darija words in Arabic script and French or English words in Latin script, as they were spoken. Do not translate, correct or summarise.\nReturn only the transcription, with no comment. If the audio is empty or unintelligible, return exactly: [inaudible]";
return [{ json: { body: { contents: [ { parts: [
  { text: instruction },
  { inline_data: { mime_type: mime, data: buf.toString('base64') } },
] } ] } } }];

// Build a Gemini request with the downloaded file inlined as base64
const bin = $input.first().binary.data;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
let mime = bin.mimeType || '';
if (!mime || mime === 'application/octet-stream') mime = "image/jpeg";
const instruction = "The user sent a photo, probably of a Tunisian administrative document or form, in French and/or Arabic. Describe it for an assistant that will help them with the related procedure:\n1. What kind of document it is (for example: passport application form, national ID card, birth certificate, receipt, RNE form).\n2. Its title and the issuing administration, if visible.\n3. The main visible fields or headings, transcribed. Do NOT transcribe personal data such as ID numbers, names, dates of birth or addresses.\n4. The language or languages of the document.\nIf it is not a document, say in one sentence what the photo shows.";
return [{ json: { body: { contents: [ { parts: [
  { text: instruction },
  { inline_data: { mime_type: mime, data: buf.toString('base64') } },
] } ] } } }];

// Turn the Qdrant search results into numbered passages for the answer agent
const res = $input.first().json || {};
const points = (res.result && (res.result.points || res.result)) || [];
const parts = [];
for (const p of points) {
  const pl = p.payload || {};
  const text = pl.content || '';
  if (!text) continue;
  const m = pl.metadata || {};
  const header = '[' + (parts.length + 1) + '] (' + [m.procedure_id, m.source_type, m.date_retrieved, m.url]
    .map(x => x || '?').join(', ') + ')';
  parts.push(header + '\n' + text);
}
const r = $('Router').first().json.output;
const u = $('User input').first().json;
return [{ json: {
  context: parts.length ? parts.join('\n\n') : 'NO RELEVANT PASSAGES FOUND',
  n_chunks: parts.length,
  text: u.text,
  chat_id: u.chat_id,
  input_type: u.input_type,
  language: r.language,
  procedure: r.procedure || '',
} }];

